/**
 * The curriculum code registry (src/data/registry/codes/*.json, generated by scripts/import-codes.mjs).
 * Checks that the files are what the script derives from the frozen research + overrides, that every
 * entry is a valid CodeEntry, and that the messy research strings were normalised, expanded and
 * resolved correctly (spot checks against values read from the research file itself).
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { CODES, codesFor, getCode, mergeCodes } from '../../src/data/codes';
import { CodeEntry, CodeKey, DOMAINS as SCHEMA_DOMAINS, SUBJECT_IDS } from '../../src/data/schema';
import { DOMAINS, OUT_DIR, OVERRIDES_PATH, RESEARCH_PATH, asciiRoman, buildRegistry, codesInString, depTokensInString, readJson, serialise } from '../../scripts/import-codes.mjs';

type Unit = { order: number; grade_level: string; in_gsat: string; gsat_track: string; curriculum_codes: string[] };
type Bridge = { curriculum_codes: string[] };
type ResearchFile = { result: Array<{ key: string; verification: { final_units?: Unit[]; final_bridging_prereqs?: Bridge[] } }> };

const research = readJson(RESEARCH_PATH) as ResearchFile;
const overrides = readJson(OVERRIDES_PATH) as Array<Record<string, unknown>>;
const built = buildRegistry(research, overrides);
const files: Record<string, unknown[]> = Object.fromEntries(DOMAINS.map((d: string) => [d, JSON.parse(readFileSync(join(OUT_DIR, `${d}.json`), 'utf8'))]));
const all = Object.values(files).flat() as CodeEntry[];
const byKey = new Map(all.map((e) => [e.key, e]));
const must = (key: string): CodeEntry => {
  const e = byKey.get(key);
  if (!e) throw new Error(`expected registry entry ${key}`);
  return e;
};
const verification = (key: string) => research.result.find((r) => r.key === key)!.verification;
const range = (prefix: string, from: number, to: number) => Array.from({ length: to - from + 1 }, (_, i) => `${prefix}${from + i}`);

describe('generated files', () => {
  it('cover exactly the schema domains (the script keeps its own copy because it may run without TS)', () => {
    expect(DOMAINS).toEqual([...SCHEMA_DOMAINS]);
  });

  it('match a fresh run of scripts/import-codes.mjs (never hand-edit them; use overrides.json)', () => {
    for (const d of DOMAINS) {
      const onDisk = readFileSync(join(OUT_DIR, `${d}.json`), 'utf8').replace(/\r\n/g, '\n');
      expect(onDisk, `${d}.json is stale: run npm run import:codes`).toBe(serialise(built.domains[d]));
    }
  });

  it('every entry is a valid schema.CodeEntry', () => {
    const bad = all.flatMap((e) => {
      const r = CodeEntry.safeParse(e);
      return r.success ? [] : [`${e.key}: ${r.error.issues.map((i) => `${i.path.join('.')} ${i.message}`).join('; ')}`];
    });
    expect(bad).toEqual([]);
  });

  it('keys are unique, ASCII CodeKeys, and each file holds only its own domain', () => {
    expect(byKey.size).toBe(all.length);
    for (const [d, list] of Object.entries(files)) {
      for (const e of list as CodeEntry[]) {
        expect(CodeKey.safeParse(e.key).success, e.key).toBe(true);
        expect(e.domain, e.key).toBe(d);
        expect(e.key.startsWith(`${d}:`), e.key).toBe(true);
      }
    }
  });

  it('prints counts per domain', () => {
    const rows = DOMAINS.map((d: string) => {
      const list = files[d] as CodeEntry[];
      const n = (v: string) => list.filter((e) => e.inGsat === v).length;
      return `${d.padEnd(9)} ${String(list.length).padStart(4)}  yes ${n('yes')}, partial ${n('partial')}, no ${n('no')}, background ${n('background')}`;
    });
    console.log(`code registry (${all.length} codes)\n  ${rows.join('\n  ')}`);
    expect(all.length).toBeGreaterThan(0);
  });
});

describe('normalisation', () => {
  it('keys use ASCII Roman numerals; `code` keeps the form the research gives', () => {
    expect(all.filter((e) => /[ⅠⅡⅢⅣⅤ]/.test(e.key))).toEqual([]);
    expect(asciiRoman('PKa-Ⅴc-1')).toBe('PKa-Vc-1');
    expect(must('nat:PKa-Vc-1').code).toBe('PKa-Ⅴc-1'); // physics: the 課綱 prints Ⅴ
    expect(must('nat:CAb-Vc-1').code).toBe('CAb-Vc-1'); // chemistry: the 課綱 mostly prints ASCII V
    expect(must('hist:Ba-V-1').code).toBe('歷Ba-Ⅴ-1');
    expect(must('civ:Aa-V-1').code).toBe('公Aa-Ⅴ-1');
    expect(must('chi:Aa-I-1').level).toBe('國小1–2');
  });

  it('strips spaces and subject prefixes from keys (地 Aa-Ⅴ-1, 數學 S-6-2, 自然 Fa-Ⅳ-1, 國小 Cb-Ⅱ-1)', () => {
    expect(must('geo:Aa-V-1').code).toBe('地Aa-Ⅴ-1');
    expect(must('math:S-6-2').code).toBe('S-6-2');
    expect(must('nat:Fa-IV-1').subjects).toEqual(['earth', 'geography']);
    expect(must('soc-elem:Cb-II-1').code).toBe('Cb-Ⅱ-1');
    expect(must('math:N-12jia-1').code).toBe('N-12甲-1');
    expect(must('math:N-12yi-1').level).toBe('12乙');
  });

  it('ignores annotations in parentheses', () => {
    const printed = codesInString("PEa-Ⅴa-1 (printed 'PEa-Va-1' in the 課綱)");
    expect(printed.flatMap((t: { parts: Array<{ body: string }> }) => t.parts.map((p) => p.body))).toEqual(['PEa-Ⅴa-1']);
    expect(must('nat:PEa-Va-1').code).toBe('PEa-Ⅴa-1');
    expect(must('nat:CMb-Vc-1').code).toBe('CMb-Vc-1');
  });

  it('puts bare-code collisions in different domains', () => {
    // 國文 Ab-Ⅴ-1 vs 公Ab-Ⅴ-1; 國中 自然 Ab-Ⅳ-1 vs 國文 Ab-Ⅳ-1; 國小 社會 Cb-Ⅱ-1 vs 國文 Cb-Ⅴ-1
    for (const key of ['chi:Ab-V-1', 'civ:Ab-V-1', 'nat:Ab-IV-1', 'chi:Ab-IV-1', 'soc-elem:Cb-II-1', 'chi:Cb-V-1']) must(key);
    expect(must('nat:Ab-IV-1').subjects).toEqual(['physics', 'chemistry', 'earth']);
  });
});

describe('ranges, slashes and wildcards', () => {
  it('expands physics elective ranges (PEb-Ⅴa-1~9 + 10~15; PKc-Ⅴa-1~3, 4~6, 7~15)', () => {
    for (const key of [...range('nat:PEb-Va-', 1, 15), ...range('nat:PKc-Va-', 1, 15), ...range('nat:PKa-Va-', 1, 13)]) {
      const e = must(key);
      expect([e.inGsat, e.gsatTrack, e.level, e.subjects], key).toEqual(['no', 'none', '選修', ['physics']]);
    }
    expect(byKey.has('nat:PEb-Va-16')).toBe(false);
    expect(byKey.has('nat:PKa-Va-14')).toBe(false);
  });

  it('expands other ranges and slash lists', () => {
    for (const key of [...range('civ:Ea-V-', 1, 4), ...range('exam:chi-B', 1, 5), ...range('nat:an-Vc-', 1, 3), 'nat:ah-Vc-1', 'nat:ah-Vc-2', ...range('nat:CJd-Va-', 1, 8)]) must(key);
    expect(byKey.has('civ:Ea-V-5')).toBe(false);
    // '數學 A-7-2~A-7-4' in a chemistry depends_on
    expect(must('nat:CJa-Vc-2').dependsOn).toEqual(expect.arrayContaining(['math:A-7-2', 'math:A-7-3', 'math:A-7-4']));
  });

  it('keeps only the cited members of a wildcard (EIc-Va-*) and reports it', () => {
    expect(must('nat:EIc-Va-1').inGsat).toBe('no');
    expect(built.unmapped.find((u: { id: string }) => u.id === 'EIc-Va-*')).toMatchObject({ kind: 'wildcard', acknowledged: true });
  });
});

describe('math (the pilot subject)', () => {
  const units = verification('math').final_units!;
  const inScope = units.filter((u) => ['10', '11A', '11B'].includes(u.grade_level));
  const TRACK: Record<string, string> = { both: 'both', 數A: 'A', 數B: 'B' };

  it('has all 58 學測 codes (10: 23, 11A: 23, 11B: 12) with the research inGsat and the right gsatTrack', () => {
    const codes = inScope.flatMap((u) => u.curriculum_codes.map((c) => ({ c, u })));
    expect(codes.length).toBe(58);
    const per = (g: string) => codes.filter(({ u }) => u.grade_level === g).length;
    expect([per('10'), per('11A'), per('11B')]).toEqual([23, 23, 12]);
    for (const { c, u } of codes) {
      const e = must(`math:${c}`);
      expect([e.inGsat, e.gsatTrack, e.level], c).toEqual([u.in_gsat, TRACK[u.gsat_track], u.grade_level]);
    }
    // the research marks three ★＃ units 'partial'; everything else in scope is 'yes'
    expect(codes.filter(({ u }) => u.in_gsat === 'partial').map(({ c }) => c)).toEqual(['N-10-5', 'N-10-7', 'D-10-1']);
  });

  it('marks 12甲/12乙 electives inGsat no, gsatTrack none', () => {
    const electives = (files.math as CodeEntry[]).filter((e) => /^math:[A-Z]-12/.test(e.key));
    expect(electives.length).toBe(26);
    expect(electives.every((e) => e.inGsat === 'no' && e.gsatTrack === 'none')).toBe(true);
  });

  it('sets whole-code ★/＃ marks from the unit titles only; part-level marks are reported, not set', () => {
    const marked = all.filter((e) => e.marks.length).map((e) => [e.key, e.marks.join('')]);
    expect(marked).toEqual([
      ['math:D-10-1', '★＃'],
      ['math:G-10-1', '＃'],
      ['math:N-10-5', '★＃'],
      ['math:N-10-7', '★＃'],
    ]);
    const partKeys = built.partMarks.map((p: { keys: string[]; marks: string[] }) => `${p.keys.join(',')} ${p.marks.join('')}`);
    expect(partKeys).toEqual(expect.arrayContaining(['math:F-11A-1 ※', 'math:G-11A-7 ※', 'math:A-11A-2 ★', 'math:G-10-7 ＃']));
  });

  it('includes every bridging code (132) as background', () => {
    const bridgeCodes = new Set(verification('math').final_bridging_prereqs!.flatMap((b) => b.curriculum_codes));
    expect(bridgeCodes.size).toBe(132);
    for (const c of bridgeCodes) expect(must(`math:${c}`).inGsat, c).toBe('background');
  });
});

describe('scope counts match the plan (docs/plan.md, Syllabus)', () => {
  const yes = (pred: (e: CodeEntry) => boolean) => all.filter((e) => e.inGsat === 'yes' && pred(e));
  const content = (e: CodeEntry) => /^[A-Z]/.test(e.key.slice(e.key.indexOf(':') + 1)); // 學習內容, not 學習表現

  it('自然: physics 49, chemistry 46, biology 26, earth 42 (163); 探究 4 strands + 14 sub-items', () => {
    const nat = (s: string) => yes((e) => e.domain === 'nat' && content(e) && e.subjects.includes(s as CodeEntry['subjects'][number])).length;
    expect([nat('physics'), nat('chemistry'), nat('biology'), nat('earth')]).toEqual([49, 46, 26, 42]);
    const inq = files.inq as CodeEntry[];
    expect(inq.filter((e) => !e.key.includes('/')).map((e) => e.key)).toEqual(['inq:argue-model', 'inq:discover', 'inq:plan', 'inq:share']);
    expect(inq.filter((e) => e.key.includes('/')).length).toBe(14);
  });

  it('歷 51, 地 77 + 3 田野實察, 公 78', () => {
    expect(yes((e) => e.domain === 'hist').length).toBe(51);
    expect(yes((e) => e.domain === 'geo' && !e.key.startsWith('geo:field-')).length).toBe(77);
    expect(['geo:field-1', 'geo:field-2', 'geo:field-3'].map((k) => must(k).code)).toEqual(['田野實察（一）', '田野實察（二）', '田野實察（三）']);
    expect(yes((e) => e.domain === 'civ').length).toBe(78);
  });

  it('國文: 33 第五學習階段 學習內容, 考試說明 A1–A6/B1–B5, 15 推薦選文', () => {
    const chiContent = all.filter((e) => /^chi:[A-Z][a-z]-V-\d+$/.test(e.key));
    expect(chiContent.length).toBe(33);
    // 書法 (Ab-Ⅴ-4) is the one the research marks 'partial'
    expect(chiContent.filter((e) => e.inGsat !== 'yes').map((e) => `${e.key} ${e.inGsat}`)).toEqual(['chi:Ab-V-4 partial']);
    expect((files.exam as CodeEntry[]).filter((e) => e.key.startsWith('exam:chi-')).map((e) => e.key)).toEqual([...range('exam:chi-A', 1, 6), ...range('exam:chi-B', 1, 5)]);
    expect((files.chi as CodeEntry[]).filter((e) => e.key.startsWith('chi:sel-')).length).toBe(15);
  });
});

describe('subjects and background codes', () => {
  it('maps every bridging code string of every subject', () => {
    const unread: string[] = [];
    for (const r of research.result) {
      for (const b of r.verification.final_bridging_prereqs ?? []) {
        for (const raw of b.curriculum_codes) if (!codesInString(raw).length) unread.push(`${r.key}: ${raw}`);
      }
    }
    expect(unread).toEqual([]);
    expect(built.unmapped.filter((u: { where: string }) => / bridge /.test(u.where))).toEqual([]);
    expect(must('soc-elem:Ac-III-1').inGsat).toBe('background'); // 國小 社會 has no 公 prefix
    expect(must('math:n-III-9').subjects).toEqual(['geography']); // '數學 n-III-9', cited only by geography
  });

  it('a 高中 code belongs to the syllabus that lists it; other subjects cite it through dependsOn', () => {
    expect(must('math:N-10-1').subjects).toEqual(['math']);
    expect(must('nat:CJa-Vc-3').dependsOn).toContain('math:N-10-1');
    expect(must('nat:PKc-Vc-6').subjects).toEqual(['physics']);
  });
});

describe('dependsOn', () => {
  it('only points at registry keys, never at itself', () => {
    const bad = all.flatMap((e) => e.dependsOn.filter((d) => !byKey.has(d) || d === e.key).map((d) => `${e.key} → ${d}`));
    expect(bad).toEqual([]);
  });

  it('maps code-like depends_on strings and ignores prose around them', () => {
    expect(must('math:N-10-1').dependsOn).toContain('math:N-3-11');
    // "國中理化 Ba-Ⅳ-2 (…). The report's Ba-Ⅳ-3 is wrong: …"
    expect(must('nat:BDa-Vc-4').dependsOn).toContain('nat:Ba-IV-2');
    expect(must('nat:BDa-Vc-4').dependsOn).not.toContain('nat:Ba-IV-3');
    // "bridge: 歷Ob-Ⅳ-1 (…), needed for the 明末清初 part because Mb-Ⅴ-1 comes later"
    expect(must('hist:Ia-V-1').dependsOn).toContain('hist:Ob-IV-1');
    expect(must('hist:Ia-V-1').dependsOn).not.toContain('hist:Mb-V-1');
    // "國中 公Bf-Ⅳ-2 and 國小 Ac-Ⅲ-2" and the item-level "公Ab-Ⅴ"
    expect(must('civ:Ad-V-1').dependsOn).toEqual(expect.arrayContaining(['civ:Bf-IV-2', 'soc-elem:Ac-III-2', 'civ:Ab-V-1', 'civ:Ab-V-4']));
    const toks = depTokensInString('Bridging: 數學 S-6-2 地圖比例尺, n-III-9 比例');
    expect(toks.map((t: { ctx: { domain: string | null } }) => t.ctx.domain)).toEqual(['math', 'math']);
  });

  it('lists known-missing dependencies with a reason in overrides.json', () => {
    const missing = built.unmapped.filter((u: { kind: string }) => u.kind === 'missing-dep').map((u: { id: string }) => u.id);
    expect(missing).toEqual(['civ:Bb-IV-1', 'civ:Bb-IV-2']);
    for (const id of missing) expect(byKey.has(id)).toBe(false);
  });
});

describe('unmapped strings and overrides', () => {
  it('every unmapped research string is acknowledged by an override, and no override is stale', () => {
    console.log(`unmapped (all acknowledged in overrides.json):\n  ${built.unmapped.map((u: { kind: string; id: string }) => `${u.kind}: ${u.id}`).join('\n  ')}`);
    expect(built.unmapped.filter((u: { acknowledged: boolean }) => !u.acknowledged)).toEqual([]);
    expect(built.stale).toEqual([]);
    for (const o of overrides) expect(typeof o.reason === 'string' && o.reason.length > 0).toBe(true);
  });

  it('applies key patches last', () => {
    for (const o of overrides.filter((x) => typeof x.key === 'string')) {
      const { key, reason: _r, raw: _w, remove, ...patch } = o as Record<string, unknown> & { key: string };
      if (remove) expect(byKey.has(key)).toBe(false);
      else expect(must(key)).toMatchObject(patch);
    }
    const patched = buildRegistry(research, [...overrides, { key: 'math:N-10-1', inGsat: 'partial', reason: 'test' }]);
    expect(patched.domains.math.find((e: CodeEntry) => e.key === 'math:N-10-1').inGsat).toBe('partial');
  });
});

describe('src/data/codes.ts', () => {
  it('loads the same entries', () => {
    expect(CODES.size).toBe(all.length);
    expect(getCode('math:N-10-1')?.title['zh-tw']).toBe('實數');
    expect(getCode('math:N-10-99')).toBeUndefined();
  });

  it('codesFor(subject) returns the codes whose subjects include it', () => {
    for (const s of SUBJECT_IDS) expect(codesFor(s).every((e) => e.subjects.includes(s)), s).toBe(true);
    expect(codesFor('math').some((e) => e.key === 'math:N-10-1')).toBe(true);
    expect(codesFor('inquiry').filter((e) => e.domain === 'inq').length).toBe(18);
    expect(codesFor('history').some((e) => e.key === 'soc-elem:Cb-II-1')).toBe(true);
  });

  const entry = (key: string, extra: Record<string, unknown> = {}) => ({ ...must('math:N-10-1'), key, dependsOn: [], ...extra });
  it('mergeCodes rejects duplicates, misfiled entries, unknown files and dangling dependsOn', () => {
    expect(() => mergeCodes({ './registry/codes/math.json': [entry('math:X-1'), entry('math:X-1')] })).toThrow(/Duplicate/);
    expect(() => mergeCodes({ './registry/codes/nat.json': [entry('math:X-1')] })).toThrow(/filed in/);
    expect(() => mergeCodes({ './registry/codes/maths.json': [] })).toThrow(/must be/);
    expect(() => mergeCodes({ './registry/codes/math.json': [entry('math:X-1', { dependsOn: ['math:Y-1'] })] })).toThrow(/depends on/);
    expect(() => mergeCodes({ './registry/codes/math.json': [entry('math:X-1', { inGsat: 'maybe' })] })).toThrow(/invalid/);
    expect(mergeCodes({ './registry/codes/math.json': [entry('math:X-1')] }).size).toBe(1);
  });
});
